scripts.detectPage:
(function() {
    /**
 * detectPage.js
 * 识别当前 GitHub 页面的结构与类型
 */

export function run(doc) {
  const loc = doc.location || window.location || {}
  const pathname = loc.pathname || ''
  const search = loc.search || ''

  // 1. 登录与认证页面
  if (pathname === '/login' || pathname.startsWith('/login/') || doc.querySelector('#login_field') || doc.querySelector('.session-authentication')) {
    return {
      origin: loc.origin || 'https://github.com',
      pathname,
      pageKind: 'login',
      hasStructure: Boolean(doc.querySelector('#login_field') || doc.querySelector('form[action*="/session"]'))
    }
  }

  // 2. 二次验证与设备核验
  if (pathname.includes('/sessions/two-factor') || doc.querySelector('input[name="otp"]') || doc.querySelector('.two-factor-help')) {
    return {
      origin: loc.origin || 'https://github.com',
      pathname,
      pageKind: 'verify',
      hasStructure: true
    }
  }

  // 3. 错误与频次受限
  if (doc.title && (doc.title.includes('Rate limit') || doc.title.includes('Whoa there!'))) {
    return {
      origin: loc.origin || 'https://github.com',
      pathname,
      pageKind: 'rate_limit',
      hasStructure: true
    }
  }
  if (doc.title && doc.title.includes('Page not found')) {
    return {
      origin: loc.origin || 'https://github.com',
      pathname,
      pageKind: 'not_found',
      hasStructure: true
    }
  }

  // 4. 搜索结果页
  if (pathname === '/search' || pathname.startsWith('/search/')) {
    const list = doc.querySelector('.repo-list') || doc.querySelector('[data-testid="results-list"]') || doc.querySelector('[data-testid="search-sub-header"]')
    const blank = doc.querySelector('.blankslate') || doc.body?.innerText?.includes('We couldn’t find any repositories')
    return {
      origin: loc.origin || 'https://github.com',
      pathname,
      pageKind: 'search',
      hasStructure: Boolean(list || blank)
    }
  }

  // 5. 趋势页
  if (pathname === '/trending' || pathname.startsWith('/trending/')) {
    const box = doc.querySelector('.Box .Box-row') || doc.querySelector('article.Box-row')
    return {
      origin: loc.origin || 'https://github.com',
      pathname,
      pageKind: 'trending',
      hasStructure: Boolean(box)
    }
  }

  // 6. 个人主页与 Tab (repositories, stars)
  if (doc.querySelector('.vcard-names') || doc.querySelector('.user-profile-bio') || doc.querySelector('nav[aria-label="User profile"]')) {
    if (search.includes('tab=repositories')) {
      return { origin: loc.origin, pathname, pageKind: 'repositories', hasStructure: true }
    }
    if (search.includes('tab=stars')) {
      return { origin: loc.origin, pathname, pageKind: 'stars', hasStructure: true }
    }
    return { origin: loc.origin, pathname, pageKind: 'profile', hasStructure: true }
  }

  // 7. 仓库详情页
  if (doc.querySelector('#repository-container-header') || doc.querySelector('strong[itemprop="name"] a') || doc.querySelector('meta[name="octolytics-dimension-repository_id"]')) {
    return { origin: loc.origin, pathname, pageKind: 'repository', hasStructure: true }
  }

  return {
    origin: loc.origin || 'https://github.com',
    pathname,
    pageKind: 'unknown',
    hasStructure: false
  }
}

    try {
      return JSON.stringify(run(document, %ARGS%));
    } catch (e) {
      return JSON.stringify({ error: e.message || 'script_error' });
    }
  })();

scripts.readCurrentIdentity:
(function() {
    /**
 * readCurrentIdentity.js
 * 提取当前 GitHub 页面中代表“已登录用户”的身份依据 (依据 project.md 第五节)
 */

export function run(doc) {
  // 1. 检查是否在明确的登录或未登录页面
  if (doc.querySelector('#login_field') || (doc.location?.pathname === '/login')) {
    return { kind: 'anonymous', accountId: null, login: null, evidence: 'login_page' }
  }

  // 2. 检查是否在二次验证或设备确认页面
  if (doc.location?.pathname?.includes('/sessions/two-factor') || doc.querySelector('input[name="otp"]')) {
    return { kind: 'verification', accountId: null, login: null, evidence: 'two_factor_prompt' }
  }

  // 3. 检查 GitHub 官方 meta 标签
  const metaActorId = doc.querySelector('meta[name="octolytics-actor-id"]')?.getAttribute('content')
  const metaActorLogin = doc.querySelector('meta[name="octolytics-actor-login"]')?.getAttribute('content')
  const metaUserLogin = doc.querySelector('meta[name="user-login"]')?.getAttribute('content')

  const login = (metaActorLogin || metaUserLogin || '').trim()
  const accountId = (metaActorId && metaActorId !== '0') ? metaActorId.trim() : null

  if (login && login !== 'undefined' && login !== 'null') {
    return {
      kind: 'authenticated',
      accountId: accountId || null,
      login,
      evidence: metaActorId ? 'octolytics_actor' : 'user_login_meta'
    }
  }

  // 4. 检查用户菜单/头像上的登录用户名
  const headerUser = doc.querySelector('[data-login]')?.getAttribute('data-login')
    || doc.querySelector('img.avatar-user')?.getAttribute('alt')?.replace(/^@/, '')
    || doc.querySelector('summary[aria-label*="View profile and more"] img')?.getAttribute('alt')?.replace(/^@/, '')

  if (headerUser && headerUser !== 'undefined' && headerUser !== 'null') {
    return {
      kind: 'authenticated',
      accountId: accountId || null,
      login: headerUser.trim(),
      evidence: 'header_avatar_user'
    }
  }

  // 5. 检查是否可见 Sign in 按钮（确定为未登录）
  const signInLink = doc.querySelector('a[href*="/login"]') || doc.querySelector('a[data-ga-click*="Sign in"]')
  if (signInLink) {
    return { kind: 'anonymous', accountId: null, login: null, evidence: 'sign_in_link_visible' }
  }

  return { kind: 'unknown', accountId: null, login: null, evidence: 'no_identity_markers' }
}

    try {
      return JSON.stringify(run(document, %ARGS%));
    } catch (e) {
      return JSON.stringify({ error: e.message || 'script_error' });
    }
  })();

scripts.readProfile:
(function() {
    /**
 * readProfile.js
 * 从 GitHub 个人页面提取公开资料与数量
 */

export function run(doc, args = {}) {
  const expectedLogin = args.expectedLogin || ''

  const nicknameEl = doc.querySelector('.p-nickname') || doc.querySelector('.vcard-username')
  const fullnameEl = doc.querySelector('.p-name') || doc.querySelector('.vcard-fullname')
  const avatarEl = doc.querySelector('img.avatar-user') || doc.querySelector('.avatar-user')
  const bioEl = doc.querySelector('.user-profile-bio') || doc.querySelector('[data-bio-text]')

  const locationEl = doc.querySelector('li[itemprop="homeLocation"]') || doc.querySelector('[itemprop="homeLocation"]')
  const companyEl = doc.querySelector('li[itemprop="worksFor"]') || doc.querySelector('[itemprop="worksFor"]')

  const repoCounter = doc.querySelector('a[href*="tab=repositories"] span.Counter') || doc.querySelector('[data-tab-item="repositories"] span.Counter')
  const followerCounter = doc.querySelector('a[href*="tab=followers"] span.Counter')
  const followingCounter = doc.querySelector('a[href*="tab=following"] span.Counter')

  const login = (nicknameEl?.innerText || '').trim() || expectedLogin
  const displayName = (fullnameEl?.innerText || '').trim() || null
  const avatarUrl = avatarEl?.getAttribute('src') || null
  const bio = (bioEl?.innerText || '').trim() || null
  const location = (locationEl?.innerText || '').trim() || null
  const company = (companyEl?.innerText || '').trim() || null

  // 尝试从页面或头像提取稳定数字 accountId
  let accountId = doc.querySelector('meta[name="octolytics-dimension-user_id"]')?.getAttribute('content')
    || doc.querySelector('[data-scope-id]')?.getAttribute('data-scope-id')
    || null

  if (!accountId && avatarUrl) {
    const m = avatarUrl.match(/\/u\/(\d+)/)
    if (m && m[1]) accountId = m[1]
  }

  return {
    accountId: accountId || null,
    login,
    displayName,
    avatarUrl,
    profileUrl: `https://github.com/${login}`,
    bio,
    location,
    company,
    publicRepoCount: repoCounter?.innerText?.trim() || null,
    followerCount: followerCounter?.innerText?.trim() || null,
    followingCount: followingCounter?.innerText?.trim() || null
  }
}

    try {
      return JSON.stringify(run(document, %ARGS%));
    } catch (e) {
      return JSON.stringify({ error: e.message || 'script_error' });
    }
  })();

scripts.readOwnedRepositories:
(function() {
    /**
 * readOwnedRepositories.js
 * 从用户的仓库列表页面提取公开仓库条目及翻页信息 (依据 project.md 第六节)
 */

export function run(doc, args = {}) {
  const expectedLogin = args.expectedLogin || ''
  const pageSeq = args.pageSeq || 1

  const listItems = Array.from(doc.querySelectorAll('#user-repositories-list li, [data-filterable-for="your-repos-filter"] li'))
  const blankslate = doc.querySelector('.blankslate')

  if (listItems.length === 0 && blankslate) {
    return {
      items: [],
      nextUrl: null,
      completion: 'end',
      pageSeq
    }
  }

  const items = []

  for (const li of listItems) {
    const titleLink = li.querySelector('a[itemprop="name codeRepository"]') || li.querySelector('h3 a')
    if (!titleLink) continue

    const name = titleLink.innerText.trim()
    const href = titleLink.getAttribute('href') || ''
    const fullName = href.replace(/^\//, '').split('?')[0] || `${expectedLogin}/${name}`

    // 检查可见性 (Public / Private)
    const label = li.querySelector('.Label--secondary')?.innerText?.toLowerCase() || ''
    let isPrivate = label.includes('private')
    let visibility = isPrivate ? 'private' : 'public'

    // 过滤私有仓库
    if (isPrivate) continue

    const descEl = li.querySelector('p[itemprop="description"]') || li.querySelector('.description')
    const langEl = li.querySelector('span[itemprop="programmingLanguage"]')
    const isFork = Boolean(li.querySelector('.fork-flag') || li.innerText.includes('Forked from'))
    const timeEl = li.querySelector('relative-time') || li.querySelector('time-ago') || li.querySelector('time')

    // 许可证提取
    let licenseSpdx = null
    const textContent = li.innerText
    if (textContent.includes('MIT License') || textContent.includes('MIT')) licenseSpdx = 'MIT'
    else if (textContent.includes('Apache-2.0') || textContent.includes('Apache 2.0')) licenseSpdx = 'Apache-2.0'
    else if (textContent.includes('GPL-3.0') || textContent.includes('GPLv3')) licenseSpdx = 'GPL-3.0'

    // Topics 标签提取
    const topicEls = Array.from(li.querySelectorAll('a.topic-tag, [data-ga-click*="topic"]'))
    const topics = topicEls.map(el => el.innerText.trim().replace(/^#/, '')).filter(Boolean)

    items.push({
      fullName,
      name,
      owner: fullName.split('/')[0] || expectedLogin,
      htmlUrl: `https://github.com/${fullName}`,
      description: descEl?.innerText?.trim() || null,
      primaryLanguage: langEl?.innerText?.trim() || null,
      topics,
      isFork,
      visibility,
      licenseSpdx,
      updatedAt: timeEl?.getAttribute('datetime') || null
    })
  }

  // 翻页与结束证据提取
  const nextBtn = doc.querySelector('.paginate-container a.next_page')
    || doc.querySelector('.paginate-container a[rel="next"]')
    || Array.from(doc.querySelectorAll('.paginate-container a')).find(a => a.innerText.includes('Next'))

  let nextUrl = null
  let completion = 'end'

  if (nextBtn && !nextBtn.hasAttribute('disabled') && !nextBtn.classList.contains('disabled')) {
    const rawHref = nextBtn.getAttribute('href')
    if (rawHref) {
      nextUrl = new URL(rawHref, 'https://github.com').toString()
      completion = 'more'
    }
  }

  return {
    items,
    nextUrl,
    completion,
    pageSeq
  }
}

    try {
      return JSON.stringify(run(document, %ARGS%));
    } catch (e) {
      return JSON.stringify({ error: e.message || 'script_error' });
    }
  })();

