scripts.readRepositoryDetail:
(function() {
    /**
 * readRepositoryDetail.js
 * 从仓库主页提取稳定数字 repoId、元数据及 README 文本内容 (依据 project.md 第六节)
 */

export function run(doc, args = {}) {
  const expectedFullName = args.expectedFullName || ''

  // 1. 提取稳定数字 repoId
  let repoId = doc.querySelector('meta[name="octolytics-dimension-repository_id"]')?.getAttribute('content')
    || doc.querySelector('[data-view-component="true"] form[action*="/star"] input[name="repository_id"]')?.value
    || null

  // 2. 规范化仓库名称与所有者
  let fullName = expectedFullName
  const repoHeader = doc.querySelector('#repository-container-header')
  if (repoHeader) {
    const ownerEl = repoHeader.querySelector('span.author a')
    const nameEl = repoHeader.querySelector('strong[itemprop="name"] a')
    if (ownerEl && nameEl) {
      fullName = `${ownerEl.innerText.trim()}/${nameEl.innerText.trim()}`
    }
  }

  const parts = fullName.split('/')
  const owner = parts[0] || ''
  const name = parts[1] || ''

  // 3. 简介与元数据
  const descEl = doc.querySelector('p[itemprop="description"]') || doc.querySelector('.f4.my-3')
  const langEl = doc.querySelector('[itemprop="programmingLanguage"]') || doc.querySelector('li.d-inline span.color-fg-default')

  // Topics
  const topicEls = Array.from(doc.querySelectorAll('a.topic-tag, [data-ga-click*="Topic"]'))
  const topics = topicEls.map(el => el.innerText.trim().replace(/^#/, '')).filter(Boolean)

  // Star & Fork 数
  const starCountEl = doc.querySelector('#repo-stars-counter-star')
    || doc.querySelector('#repo-stars-counter-unstar')
    || doc.querySelector('a[href*="/stargazers"] span.Counter')
  const forkCountEl = doc.querySelector('#repo-network-counter')
    || doc.querySelector('a[href*="/forks"] span.Counter')

  // 许可证 License
  let licenseSpdx = null
  const licenseEl = doc.querySelector('a[href*="/LICENSE"] h3')
    || doc.querySelector('svg.octicon-law + span')
    || Array.from(doc.querySelectorAll('a[href*="/LICENSE"]')).find(a => a.innerText.includes('License'))
  if (licenseEl) {
    licenseSpdx = licenseEl.innerText.trim().replace(/License$/i, '').trim()
  }

  // 4. README 文本内容 (提取纯文本，去除脚本与多余格式，上限 8000 字符)
  let readmeText = null
  const readmeArticle = doc.querySelector('#readme article') || doc.querySelector('.markdown-body')
  if (readmeArticle) {
    // 简单获取文本并去除连续空白
    const text = (readmeArticle.innerText || '').replace(/\s+/g, ' ').trim()
    readmeText = text.slice(0, 8000)
  }

  return {
    repoId: repoId ? String(repoId) : null,
    owner,
    name,
    fullName,
    htmlUrl: `https://github.com/${fullName}`,
    description: descEl?.innerText?.trim() || null,
    primaryLanguage: langEl?.innerText?.trim() || null,
    topics,
    starCount: starCountEl?.innerText?.trim() || null,
    forkCount: forkCountEl?.innerText?.trim() || null,
    licenseSpdx,
    readmeText
  }
}

    try {
      return JSON.stringify(run(document, %ARGS%));
    } catch (e) {
      return JSON.stringify({ error: e.message || 'script_error' });
    }
  })();

scripts.readRepositoryStarState:
(function() {
    /**
 * readRepositoryStarState.js
 * 读取目标仓库主操作区的当前 Star 状态 (starred / unstarred / unknown)
 */

export function run(doc, args = {}) {
  // 只定位目标仓库主操作区中的 Star 控件（排除 README 内按钮或其它无关按钮）
  const container = doc.querySelector('#repository-container-header') || doc.querySelector('.pagehead-actions') || doc

  const unstarBtn = container.querySelector('form[action*="/unstar"] button')
    || container.querySelector('button[aria-label*="Unstar this repository"]')
    || container.querySelector('[data-ga-click*="Unstar"]')

  const starBtn = container.querySelector('form[action*="/star"]:not([action*="/unstar"]) button')
    || container.querySelector('button[aria-label*="Star this repository"]')
    || container.querySelector('[data-ga-click*="Star"]:not([data-ga-click*="Unstar"])')

  const now = Date.now()

  if (unstarBtn && (!starBtn || unstarBtn.offsetParent !== null)) {
    return { state: 'starred', starred: true, observedAt: now }
  }

  if (starBtn && (!unstarBtn || starBtn.offsetParent !== null)) {
    return { state: 'unstarred', starred: false, observedAt: now }
  }

  // 检查按钮文本与 svg 图标
  const allBtns = Array.from(container.querySelectorAll('button'))
  for (const b of allBtns) {
    const text = b.innerText.trim().toLowerCase()
    if (text === 'starred' || text.startsWith('unstar')) {
      return { state: 'starred', starred: true, observedAt: now }
    }
    if (text === 'star') {
      return { state: 'unstarred', starred: false, observedAt: now }
    }
  }

  return { state: 'unknown', starred: null, observedAt: now }
}

    try {
      return JSON.stringify(run(document, %ARGS%));
    } catch (e) {
      return JSON.stringify({ error: e.message || 'script_error' });
    }
  })();

scripts.setRepositoryStar:
(function() {
    /**
 * setRepositoryStar.js
 * 定位目标仓库主操作区按钮，执行单次原生网页点击或表单提交操作 (依据 project.md 第六节)
 */

export function run(doc, args = {}) {
  const desiredStarred = Boolean(args.desiredStarred)
  const container = doc.querySelector('#repository-container-header') || doc.querySelector('.pagehead-actions') || doc

  if (desiredStarred) {
    // 目标为 Star，寻找 Star 按钮并点击
    const starBtn = container.querySelector('form[action*="/star"]:not([action*="/unstar"]) button')
      || container.querySelector('button[aria-label*="Star this repository"]')
      || Array.from(container.querySelectorAll('button')).find(b => b.innerText.trim().toLowerCase() === 'star')

    if (starBtn && typeof starBtn.click === 'function') {
      starBtn.click()
      return { clicked: true, desiredStarred: true, action: 'clicked_star' }
    }

    const starForm = container.querySelector('form[action*="/star"]:not([action*="/unstar"])')
    if (starForm && typeof starForm.submit === 'function') {
      starForm.submit()
      return { clicked: true, desiredStarred: true, action: 'submitted_star_form' }
    }
  } else {
    // 目标为 Unstar，寻找 Unstar 按钮并点击
    const unstarBtn = container.querySelector('form[action*="/unstar"] button')
      || container.querySelector('button[aria-label*="Unstar this repository"]')
      || Array.from(container.querySelectorAll('button')).find(b => {
        const t = b.innerText.trim().toLowerCase()
        return t === 'starred' || t.startsWith('unstar')
      })

    if (unstarBtn && typeof unstarBtn.click === 'function') {
      unstarBtn.click()
      return { clicked: true, desiredStarred: false, action: 'clicked_unstar' }
    }

    const unstarForm = container.querySelector('form[action*="/unstar"]')
    if (unstarForm && typeof unstarForm.submit === 'function') {
      unstarForm.submit()
      return { clicked: true, desiredStarred: false, action: 'submitted_unstar_form' }
    }
  }

  return {
    clicked: false,
    desiredStarred,
    reason: 'target_button_not_found'
  }
}

    try {
      return JSON.stringify(run(document, %ARGS%));
    } catch (e) {
      return JSON.stringify({ error: e.message || 'script_error' });
    }
  })();

scripts.readSearchResults:
(function() {
    /**
 * readSearchResults.js
 * 从 GitHub 搜索页面提取仓库搜索候选条目及翻页信息 (依据 project.md 第六节)
 */

export function run(doc, args = {}) {
  const pageSeq = args.pageSeq || 1

  const rows = Array.from(doc.querySelectorAll('.repo-list-item, [data-testid="results-list"] > div, .search-title a'))
  const blankslate = doc.querySelector('.blankslate') || doc.body?.innerText?.includes('We couldn’t find any repositories')

  if (rows.length === 0 && blankslate) {
    return {
      items: [],
      nextUrl: null,
      completion: 'end',
      pageSeq
    }
  }

  const items = []
  const seenKeys = new Set()

  const resultCards = Array.from(doc.querySelectorAll('.repo-list-item, [data-testid="results-list"] > div'))

  for (const card of resultCards) {
    const titleLink = card.querySelector('a.v-align-middle') || card.querySelector('h3 a') || card.querySelector('a[href*="/"]')
    if (!titleLink) continue

    const href = titleLink.getAttribute('href') || ''
    const cleanHref = href.replace(/^\//, '').split('?')[0]
    if (!cleanHref || !cleanHref.includes('/') || cleanHref.startsWith('search')) continue

    const parts = cleanHref.split('/')
    if (parts.length < 2) continue

    const fullName = `${parts[0]}/${parts[1]}`
    if (seenKeys.has(fullName.toLowerCase())) continue
    seenKeys.add(fullName.toLowerCase())

    const descEl = card.querySelector('p') || card.querySelector('.mb-1')
    const langEl = card.querySelector('[itemprop="programmingLanguage"]') || card.querySelector('span.color-fg-muted')
    const starEl = card.querySelector('a[href*="/stargazers"]')
    const timeEl = card.querySelector('relative-time') || card.querySelector('time')

    const topicEls = Array.from(card.querySelectorAll('a.topic-tag, [data-ga-click*="topic"]'))
    const topics = topicEls.map(el => el.innerText.trim().replace(/^#/, '')).filter(Boolean)

    items.push({
      fullName,
      owner: parts[0],
      name: parts[1],
      htmlUrl: `https://github.com/${fullName}`,
      description: descEl?.innerText?.trim() || null,
      primaryLanguage: langEl?.innerText?.trim() || null,
      starCount: starEl?.innerText?.trim() || null,
      topics,
      updatedAt: timeEl?.getAttribute('datetime') || null
    })
  }

  // 翻页链接
  const nextBtn = doc.querySelector('a.next_page')
    || doc.querySelector('a[rel="next"]')
    || Array.from(doc.querySelectorAll('.paginate-container a, nav[aria-label="Pagination"] a')).find(a => a.innerText.includes('Next'))

  let nextUrl = null
  let completion = 'end'

  if (nextBtn && !nextBtn.hasAttribute('disabled') && !nextBtn.classList.contains('disabled')) {
    const rawHref = nextBtn.getAttribute('href')
    if (rawHref) {
      nextUrl = new URL(rawHref, 'https://github.com').toString()
      completion = 'more'
    }
  }

  return {
    items,
    nextUrl,
    completion,
    pageSeq
  }
}

    try {
      return JSON.stringify(run(document, %ARGS%));
    } catch (e) {
      return JSON.stringify({ error: e.message || 'script_error' });
    }
  })();

